package com.digitalbase.ticketing.service;import com.digitalbase.ticketing.dto.CompanySlaOverviewResponse;import com.digitalbase.ticketing.dto.SlaHourSummaryResponse;import com.digitalbase.ticketing.enums.SlaStatus;import org.springframework.data.domain.Page;public interface SlaManagementService {    /**     * Top 4 Boxes (Summary) အတွက် Data တွက်ထုတ်ပေးမည့် Method     * @return SlaHourSummaryResponse (Total Companies, Hours, Low Balance Count)     */    SlaHourSummaryResponse getSlaSummary();    /**     * Company SLA Overview ဇယားနှင့် Dropdown Filter အတွက် Data တွက်ထုတ်ပေးမည့် Method     * @param searchKeyword (Optional) ကုမ္ပဏီအမည်ဖြင့် ရှာရန်     * @param statusFilter (Optional) SLA Status ဖြင့် စစ်ထုတ်ရန် (ဥပမာ: LOW_BALANCE)     * @param page Page Number     * @param size Page Size     * @return Page<CompanySlaOverviewResponse>     */    Page<CompanySlaOverviewResponse> getCompanySlaOverview(String searchKeyword, SlaStatus statusFilter, int page, int size);}